      return;
    }
    if (this.store.list().some((p) => p.from <= to && from <= p.to)) {
      this.error.set('That period overlaps another.');
      return;
    }
    this.submitting = true;
    try {
      await this.store.add(sheet, name, from, to);
      this.name.set('');
      this.from.set('');
      this.to.set('');
    } catch (err) {
      this.error.set(
